// src/nodeWidths.ts
var NODE_WIDTHS = [
  {
    value: "depth",
    label: "By depth",
    description: "Thicker the more paths carry a node, on the square root of its depth against the mean. A graph with one depth everywhere draws uniform."
  },
  {
    value: "uniform",
    label: "Uniform",
    description: "Every node the same thickness."
  }
];
var NODE_WIDTH_VALUES = NODE_WIDTHS.map((w) => w.value);
var MIN_FACTOR = 0.3;
var MAX_FACTOR = 3;
function meanDepth(graph) {
  let weighted = 0;
  let length = 0;
  for (const node of graph.nodes) {
    weighted += node.depth * node.length;
    length += node.length;
  }
  return length > 0 ? weighted / length : 0;
}
function depthWidthFactor(node, mean) {
  if (!(mean > 0) || !(node.depth > 0)) {
    return 1;
  }
  return Math.min(
    MAX_FACTOR,
    Math.max(MIN_FACTOR, Math.sqrt(node.depth / mean))
  );
}
function nodeWidthPx(node, contigThickness, nodeWidth, mean) {
  return contigThickness * (nodeWidth === "depth" ? depthWidthFactor(node, mean) : 1);
}
function maxNodeWidthPx(contigThickness, nodeWidth) {
  return contigThickness * (nodeWidth === "depth" ? MAX_FACTOR : 1);
}
function nodeInk(graph, nodeById, contigThickness, nodeWidth) {
  const mean = graph ? meanDepth(graph) : 0;
  return {
    maxHalfWidthPx: maxNodeWidthPx(contigThickness, nodeWidth) / 2,
    halfWidthPx: (id) => {
      const node = nodeById?.get(id);
      return node ? nodeWidthPx(node, contigThickness, nodeWidth, mean) / 2 : contigThickness / 2;
    }
  };
}

export {
  NODE_WIDTHS,
  NODE_WIDTH_VALUES,
  meanDepth,
  depthWidthFactor,
  nodeWidthPx,
  maxNodeWidthPx,
  nodeInk
};
